/** A time a plan was paused: its dates on or after the day it was paused and before the day it was
 *  resumed are skipped, not postponed. */
@Entity
@Table(name = "plan_pause")
public class PlanPause {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "plan_id", nullable = false)
    private Long planId;

    /** The sheet's today when the plan was paused. */
    @Column(name = "paused_on", nullable = false, updatable = false)
    private LocalDate pausedOn;

    /** The sheet's today when the plan was resumed; null while it is still paused. */
    @Column(name = "resumed_on")
    private LocalDate resumedOn;

    protected PlanPause() {
    }

    public PlanPause(Long planId, LocalDate pausedOn) {
        this.planId = planId;
        this.pausedOn = pausedOn;
    }

    public Long getId() {
        return id;
    }

    public Long getPlanId() {
        return planId;
    }

    public LocalDate getPausedOn() {
        return pausedOn;
    }

    public LocalDate getResumedOn() {
        return resumedOn;
    }

    public boolean isOpen() {
        return resumedOn == null;
    }

    public void resume(LocalDate on) {
        this.resumedOn = on;
    }

    /** Whether the plan date falls in this pause, and so is skipped. */
    public boolean skips(LocalDate date) {
        return !date.isBefore(pausedOn) && (resumedOn == null || date.isBefore(resumedOn));
    }
}
