package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

/** A person's plan: a DRAFT claim of its amount (two decimals) for every plan date up to its end. The
 *  plan dates are its start and then every so many days, or, for a monthly plan, its day of the month
 *  in every month from the start's month (a day beyond the month's length on its last day), those
 *  before the start left out. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every so many days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) a monthly plan runs on; null for one that runs every so many days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The sheet's today when the plan was added. */
    @Column(name = "made_on", nullable = false, updatable = false)
    private LocalDate madeOn;

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end, LocalDate madeOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
        this.madeOn = madeOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    public LocalDate getMadeOn() {
        return madeOn;
    }

    /** The plan's dates up to its end and the day given, those skipped left out, the earliest first. */
    public List<LocalDate> datesUpTo(LocalDate upTo, Predicate<LocalDate> skipped) {
        LocalDate last = end.isBefore(upTo) ? end : upTo;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last) && !skipped.test(d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            if (!skipped.test(d)) {
                dates.add(d);
            }
        }
        return dates;
    }

    /** The first so many plan dates after the day given and on or before its end, those skipped left
     *  out, the earliest first. */
    public List<LocalDate> datesAfter(LocalDate after, int count, Predicate<LocalDate> skipped) {
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            YearMonth m = YearMonth.from(after.isBefore(start) ? start : after);
            for (; dates.size() < count && !m.atDay(1).isAfter(end); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && d.isAfter(after) && !d.isAfter(end) && !skipped.test(d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        LocalDate d = start;
        if (!after.isBefore(start)) {
            d = start.plusDays((ChronoUnit.DAYS.between(start, after) / every + 1) * every);
        }
        for (; dates.size() < count && !d.isAfter(end); d = d.plusDays(every)) {
            if (!skipped.test(d)) {
                dates.add(d);
            }
        }
        return dates;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/plans")
public class PlanController {

    /** A plan as the screen shows it, with how many claims it has made so far and its next dates: the
     *  first five plan dates after the sheet's today and on or before its end, those a pause skips left
     *  out, and whether it is paused now. */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every,
            Integer day, LocalDate end, int generated, List<LocalDate> nextDates, boolean paused,
            List<ChangeView> changes) {
        static PlanView of(Plan plan, int generated, List<PlanPause> pauses, List<PlanChange> changes,
                LocalDate today) {
            return new PlanView(plan.getId(), plan.getPersonId(),
                    PlanService.amountAfter(plan, changes).toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), generated,
                    plan.datesAfter(today, NEXT_DATES, d -> PlanService.skipped(pauses, d)),
                    pauses.stream().anyMatch(PlanPause::isOpen),
                    changes.stream().map(c -> new ChangeView(c.getChangedOn(), c.getAmount().toPlainString()))
                            .toList());
        }
    }

    /** A change of a plan's amount: the sheet's today when it was made, and the new amount. */
    public record ChangeView(LocalDate on, String amount) {
    }

    /** A plan's new amount as typed; the service checks it. */
    public record AmountRequest(@Size(max = 50) String amount) {
    }

    /** How many next dates a plan shows. */
    private static final int NEXT_DATES = 5;

    /** A plan's fields as typed: the amount, interval and day of the month are checked by the service;
     *  a blank start takes the sheet's today. */
    public record PlanRequest(@NotNull Long personId, @Size(max = 50) String amount, LocalDate start,
            @Size(max = 50) String every, @Size(max = 50) String day, LocalDate end) {
    }

    /** The claims a generate made, in the order it made them, and the sheet's plans after it. */
    public record GenerateView(List<ClaimView> made, List<PlanView> plans) {
    }

    private final PlanService service;
    private final ClaimService claims;
    private final RollupService rollups;
    private final SheetService sheets;

    public PlanController(PlanService service, ClaimService claims, RollupService rollups, SheetService sheets) {
        this.service = service;
        this.claims = claims;
        this.rollups = rollups;
        this.sheets = sheets;
    }

    /** The sheet's plans in the order they were added: as they stand now, or as they stood at the end
     *  of the screen's as-of date. */
    @GetMapping
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        return views(sheetId.trim(), AsOf.parse(asOfHeader));
    }

    /** Add a plan for a person on the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PlanRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return PlanView.of(service.add(sheet, by, request.personId(), request.amount(), request.start(),
                request.every(), request.day(), request.end()), 0, List.of(), List.of(), sheets.today(sheet));
    }

    /** Pause the plan from the sheet's today; refused when it is paused already. */
    @PostMapping("/{planId}/pause")
    public PlanView pause(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return paused(sheetId, planId, user, true);
    }

    /** Resume the paused plan on the sheet's today; refused when it is running. */
    @PostMapping("/{planId}/resume")
    public PlanView resume(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return paused(sheetId, planId, user, false);
    }

    /** Change the plan's amount on the sheet's today; refused when the amount is bad. */
    @PostMapping("/{planId}/amount")
    public PlanView amount(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated AmountRequest request) {
        String sheet = sheetId.trim();
        Plan plan = service.changeAmount(sheet, SignedInUser.decode(user), planId, request.amount());
        return views(sheet, null).stream().filter(v -> v.id().equals(plan.getId())).findFirst().orElseThrow();
    }

    private PlanView paused(String sheetId, Long planId, String user, boolean on) {
        String sheet = sheetId.trim();
        Plan plan = service.pause(sheet, SignedInUser.decode(user), planId, on);
        return views(sheet, null).stream().filter(v -> v.id().equals(plan.getId())).findFirst().orElseThrow();
    }

    /** Make the plans' claims due by the sheet's today, then record the figures they moved. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        List<Claim> made = rollups.track(sheet, by, () -> service.generate(sheet, by));
        return new GenerateView(made.stream()
                .map(c -> ClaimView.of(c, claims.roundsBy(sheet, c), claims.logOf(c.getId()), List.of()))
                .toList(), views(sheet, null));
    }

    private List<PlanView> views(String sheet, LocalDate asOf) {
        List<Plan> them = service.list(sheet, asOf);
        Map<Long, Integer> generated = service.generated(them, asOf);
        Map<Long, List<PlanPause>> pauses = service.pauses(them, asOf);
        Map<Long, List<PlanChange>> changes = service.changes(them, asOf);
        LocalDate today = sheets.today(sheet);
        return them.stream().map(p -> PlanView.of(p, generated.getOrDefault(p.getId(), 0),
                pauses.getOrDefault(p.getId(), List.of()), changes.getOrDefault(p.getId(), List.of()), today))
                .toList();
    }

    /** A bad amount (added or changed), interval or day of the month, an end before the start, pausing a paused plan or
     *  resuming a running one, or a date that is not a real yyyy-mm-dd date. */
    @ExceptionHandler({PlanRefusedException.class, HttpMessageNotReadableException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void refused() {
    }

    /** A claim the form would refuse after all. */
    @ExceptionHandler({PeriodClosedException.class, PersonRetiredException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The plans on a sheet, and the generate that makes their claims. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PlanClaimRepository made;
    private final PlanPauseRepository pauses;
    private final PlanChangeRepository changes;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final SettingService settings;
    private final Audit audit;

    public PlanService(PlanRepository plans, PlanClaimRepository made, PlanPauseRepository pauses,
            PlanChangeRepository changes, PersonRepository people, ClaimService claims, SheetService sheets, SettingService settings, Audit audit) {
        this.plans = plans;
        this.made = made;
        this.pauses = pauses;
        this.changes = changes;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's plans in the order they were added: as they stand now, or those added by the end
     *  of the as-of date. */
    public List<Plan> list(String sheetId, LocalDate asOf) {
        return plans.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> asOf == null || !p.getMadeOn().isAfter(asOf))
                .toList();
    }

    /** How many claims each plan has made, by plan id: so far, or by the end of the as-of date. */
    public Map<Long, Integer> generated(List<Plan> them, LocalDate asOf) {
        Map<Long, Integer> counts = new HashMap<>();
        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            if (asOf == null || !c.getMadeOn().isAfter(asOf)) {
                counts.merge(c.getPlanId(), 1, Integer::sum);
            }
        }
        return counts;
    }

    /** Each plan's pauses, by plan id: as they stand now, or as they stood at the end of the as-of
     *  date (a pause made after it left out, one resumed after it still open). */
    public Map<Long, List<PlanPause>> pauses(List<Plan> them, LocalDate asOf) {
        Map<Long, List<PlanPause>> byPlan = new HashMap<>();
        for (PlanPause p : pauses.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            if (asOf != null && p.getPausedOn().isAfter(asOf)) {
                continue;
            }
            PlanPause shown = p;
            if (asOf != null && p.getResumedOn() != null && p.getResumedOn().isAfter(asOf)) {
                shown = new PlanPause(p.getPlanId(), p.getPausedOn());
            }
            byPlan.computeIfAbsent(p.getPlanId(), k -> new ArrayList<>()).add(shown);
        }
        return byPlan;
    }

    /** Each plan's amount changes, oldest first, by plan id: so far, or those made by the end of the
     *  as-of date. */
    public Map<Long, List<PlanChange>> changes(List<Plan> them, LocalDate asOf) {
        Map<Long, List<PlanChange>> byPlan = new HashMap<>();
        for (PlanChange c : changes.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            if (asOf == null || !c.getChangedOn().isAfter(asOf)) {
                byPlan.computeIfAbsent(c.getPlanId(), k -> new ArrayList<>()).add(c);
            }
        }
        return byPlan;
    }

    /** The plan's amount after its changes: that of the latest, or the one it was added with. */
    public static BigDecimal amountAfter(Plan plan, List<PlanChange> them) {
        return them.isEmpty() ? plan.getAmount() : them.get(them.size() - 1).getAmount();
    }

    /** Change the plan's amount on the sheet's today: an amount of 0.00 or more with up to two decimals.
     *  The claims it generates from then on take it; those it made already keep theirs. */
    @Transactional
    public Plan changeAmount(String sheetId, String user, Long planId, String amount) {
        sheets.lock(sheetId);
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new NoSuchElementException("No plan " + planId + " on sheet " + sheetId));
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
        BigDecimal figure = amountOf(amount);
        changes.saveAndFlush(new PlanChange(planId, sheets.today(sheetId), figure));
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " start=" + plan.getStart() + " amount=" + figure.toPlainString());
        return plan;
    }

    /** Whether the plan date falls in one of the pauses, and so is skipped. */
    public static boolean skipped(List<PlanPause> them, LocalDate date) {
        return them.stream().anyMatch(p -> p.skips(date));
    }

    /** Pause the plan from the sheet's today, or resume it on the sheet's today; pausing a paused plan or
     *  resuming a running one is refused. */
    @Transactional
    public Plan pause(String sheetId, String user, Long planId, boolean on) {
        sheets.lock(sheetId);
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new NoSuchElementException("No plan " + planId + " on sheet " + sheetId));
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
        LocalDate today = sheets.today(sheetId);
        Optional<PlanPause> open = pauses.findFirstByPlanIdAndResumedOnIsNull(planId);
        if (on) {
            if (open.isPresent()) {
                throw new PlanRefusedException("The plan is paused already");
            }
            pauses.saveAndFlush(new PlanPause(planId, today));
        } else {
            PlanPause pause = open.orElseThrow(() -> new PlanRefusedException("The plan is not paused"));
            pause.resume(today);
            pauses.saveAndFlush(pause);
        }
        audit.recordOnCommit((on ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStart());
        return plan;
    }

    /** Add a plan for a person: an amount of 0.00 or more with up to two decimals, a start (blank: the
     *  sheet's today), either every so many days (a whole number, at least 1) or monthly on a day of the
     *  month (1 to 31), and an end on or after the start. */
    @Transactional
    public Plan add(String sheetId, String user, Long personId, String amount, LocalDate start, String every,
            String day, LocalDate end) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
        BigDecimal figure = amountOf(amount);
        boolean monthly = day != null && !day.isBlank();
        if (monthly && every != null && !every.isBlank()) {
            throw new PlanRefusedException("A plan runs either every so many days or on a day of the month");
        }
        Integer days = monthly ? null : everyOf(every);
        Integer dayOfMonth = monthly ? dayOf(day) : null;
        LocalDate today = sheets.today(sheetId);
        LocalDate from = start != null ? start : today;
        if (end == null || end.isBefore(from)) {
            throw new PlanRefusedException("A plan must end on or after its start");
        }
        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, figure, from, days, dayOfMonth, end, today));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + saved.getAmount().toPlainString() + " start=" + saved.getStart()
                + (monthly ? " day=" + saved.getDay() : " every=" + saved.getEvery()) + " end=" + saved.getEnd());
        return saved;
    }

    /** For every plan on the sheet, in the order they were added, add a DRAFT claim of its amount (that of its latest change, if any) with
     *  an empty note for each plan date up to its end and the sheet's today it has made none for yet,
     *  as the claim form would, a date a pause skips left out; a date the form refuses is passed over, to be tried again next time.
     *  The claims made, in the order they were; a viewer makes none. */
    @Transactional
    public List<Claim> generate(String sheetId, String user) {
        if (settings.isViewer(sheetId, user)) {
            return List.of();
        }
        sheets.lock(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Plan> them = plans.findBySheetIdOrderByIdAsc(sheetId);
        Set<String> done = new HashSet<>();
        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            done.add(c.getPlanId() + "@" + c.getDate());
        }
        Map<Long, List<PlanPause>> paused = pauses(them, null);
        Map<Long, List<PlanChange>> changed = changes(them, null);
        List<Claim> added = new ArrayList<>();
        for (Plan plan : them) {
            List<PlanPause> its = paused.getOrDefault(plan.getId(), List.of());
            BigDecimal amount = amountAfter(plan, changed.getOrDefault(plan.getId(), List.of()));
            for (LocalDate date : plan.datesUpTo(today, d -> skipped(its, d))) {
                if (done.contains(plan.getId() + "@" + date)
                        || !claims.accepts(sheetId, plan.getPersonId(), date)) {
                    continue;
                }
                Claim claim = claims.add(sheetId, user, plan.getPersonId(), amount, date, "", null);
                made.saveAndFlush(new PlanClaim(plan.getId(), date, claim.getId(), today));
                added.add(claim);
            }
        }
        return added;
    }

    private static BigDecimal amountOf(String amount) {
        BigDecimal figure;
        try {
            figure = new BigDecimal(amount == null ? "" : amount.trim());
        } catch (NumberFormatException e) {
            throw new PlanRefusedException("The amount is not a number");
        }
        if (figure.signum() < 0 || figure.scale() > 2 || figure.precision() - figure.scale() > 10) {
            throw new PlanRefusedException("The amount must be 0.00 or more, with up to two decimals");
        }
        return figure.setScale(2);
    }

    private static int everyOf(String every) {
        String typed = every == null ? "" : every.trim();
        if (!typed.matches("\\d{1,6}") || Integer.parseInt(typed) < 1) {
            throw new PlanRefusedException("A plan runs every whole number of days, at least 1");
        }
        return Integer.parseInt(typed);
    }

    private static int dayOf(String day) {
        String typed = day.trim();
        if (!typed.matches("\\d{1,2}") || Integer.parseInt(typed) < 1 || Integer.parseInt(typed) > 31) {
            throw new PlanRefusedException("A monthly plan runs on a day of the month, 1 to 31");
        }
        return Integer.parseInt(typed);
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A plan date a plan has made its claim for. */
@Entity
@Table(name = "plan_claim")
public class PlanClaim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "plan_id", nullable = false)
    private Long planId;

    @Column(name = "plan_date", nullable = false)
    private LocalDate date;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    /** The sheet's today when the claim was made. */
    @Column(name = "made_on", nullable = false, updatable = false)
    private LocalDate madeOn;

    protected PlanClaim() {
    }

    public PlanClaim(Long planId, LocalDate date, Long claimId, LocalDate madeOn) {
        this.planId = planId;
        this.date = date;
        this.claimId = claimId;
        this.madeOn = madeOn;
    }

    public Long getId() {
        return id;
    }

    public Long getPlanId() {
        return planId;
    }

    public LocalDate getDate() {
        return date;
    }

    public Long getClaimId() {
        return claimId;
    }

    public LocalDate getMadeOn() {
        return madeOn;
    }
}
